import{_ as e,H as l,f as a,i as d}from"./chunks/framework.DLd0CbzH.js";const y=JSON.parse('{"title":"Финансовая модель и ресурсный план — Agelto","description":"","frontmatter":{"type":"concept","tags":["agelto","business","finance","unit-economics"],"created":"2026-06-11T00:00:00.000Z","updated":"2026-06-11T00:00:00.000Z"},"headers":[],"relativePath":"01_Business/03_Financial_Model.md","filePath":"01_Business/03_Financial_Model.md"}'),r={name:"01_Business/03_Financial_Model.md"};function n(i,t,s,g,o,h){return l(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="финансовая-модель-и-ресурсныи-план-—-agelto" tabindex="-1">Финансовая модель и ресурсный план — Agelto <a class="header-anchor" href="#финансовая-модель-и-ресурсныи-план-—-agelto" aria-label="Permalink to &quot;Финансовая модель и ресурсный план — Agelto&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">Источник</p><p>Выжимка из дипломной работы (гл. 2.3, 3.1–3.3), оригинал — архив <code>assets/_Диплом v1.1.docx</code>. Тарифная сетка — [[BRD (Agelto)]] §7.1, риски — [[Risk_Register (Agelto)]].</p></div><hr><h2 id="_1-модель-монетизации" tabindex="-1">1. Модель монетизации <a class="header-anchor" href="#_1-модель-монетизации" aria-label="Permalink to &quot;1. Модель монетизации&quot;">​</a></h2><p>Три потока дохода:</p><ol><li><strong>Подписка (MRR)</strong> — базовая плата за платформу (тарифы Start 25к / Business 75к / Enterprise от 200к ₽/мес — детали в [[BRD (Agelto)]] §7.1)</li><li><strong>Usage-based</strong> — оплата декомпозиции смет сверх лимита тарифа (pay-per-lead)</li><li><strong>Setup &amp; Professional Services</strong> — разовая интеграция «под ключ» (CRM, обучение) — [[Onboarding]]</li></ol><p><strong>Freemium Light (запуск 2026):</strong> бесплатный доступ к списку тендеров с декомпозицией только 3 первых позиций сметы — демо точности. ⚠️ Конфликтует с BRD F-MON-2 — резолюция: [[Открытые вопросы (Agelto)]] P5.</p><p><strong>Success Fee</strong> (комиссия за крупные закрытые сделки) — вспомогательная модель, за горизонтом 3-летнего плана.</p><h2 id="_2-roi-аргумент-для-продаж" tabindex="-1">2. ROI-аргумент для продаж <a class="header-anchor" href="#_2-roi-аргумент-для-продаж" aria-label="Permalink to &quot;2. ROI-аргумент для продаж&quot;">​</a></h2><p>Сметчик-аналитик: ~120 000 ₽/мес (с налогами и местом), обрабатывает 40–60 сложных смет/мес. Тариф Business (75 000 ₽) — до 300 смет/мес: <strong>в 5–6 раз больше объёма за 60% стоимости сотрудника</strong>. Окупаемость для клиента — первый месяц.</p><h2 id="_3-capex-инвестфаза-9-мес" tabindex="-1">3. CAPEX (инвестфаза, 9 мес) <a class="header-anchor" href="#_3-capex-инвестфаза-9-мес" aria-label="Permalink to &quot;3. CAPEX (инвестфаза, 9 мес)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Группа</th><th style="text-align:right;">Сумма, тыс. ₽</th></tr></thead><tbody><tr><td style="text-align:left;">Проектирование и R&amp;D (архитектура, модели, схема БД)</td><td style="text-align:right;">3 200</td></tr><tr><td style="text-align:left;">Разработка ядра (парсеры ЕИС, декомпозиция, pgvector)</td><td style="text-align:right;">6 800</td></tr><tr><td style="text-align:left;">Frontend и UX/UI</td><td style="text-align:right;">2 600</td></tr><tr><td style="text-align:left;">Подготовка данных (golden dataset 10 000+ смет)</td><td style="text-align:right;">2 100</td></tr><tr><td style="text-align:left;">Инфраструктура (GPU, лицензии, CI/CD)</td><td style="text-align:right;">1 900</td></tr><tr><td style="text-align:left;">Маркетинговый старт</td><td style="text-align:right;">1 500</td></tr><tr><td style="text-align:left;">Резерв на итерации (10%)</td><td style="text-align:right;">1 800</td></tr><tr><td style="text-align:left;"><strong>Итого</strong></td><td style="text-align:right;"><strong>19 900</strong></td></tr></tbody></table><h2 id="_4-opex-ежемесячно" tabindex="-1">4. OPEX (ежемесячно) <a class="header-anchor" href="#_4-opex-ежемесячно" aria-label="Permalink to &quot;4. OPEX (ежемесячно)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Статья</th><th style="text-align:right;">Тыс. ₽</th></tr></thead><tbody><tr><td style="text-align:left;">ФОТ поддержки и продаж</td><td style="text-align:right;">1 200</td></tr><tr><td style="text-align:left;">Облачная инфраструктура</td><td style="text-align:right;">180</td></tr><tr><td style="text-align:left;">Маркетинг (≈ CAC-бюджет)</td><td style="text-align:right;">450</td></tr><tr><td style="text-align:left;">Административные</td><td style="text-align:right;">120</td></tr><tr><td style="text-align:left;"><strong>Итого</strong></td><td style="text-align:right;"><strong>1 950</strong> (~23,4 млн ₽/год)</td></tr></tbody></table><h2 id="_5-эффективность-dcf-ставка-20-горизонт-3-года" tabindex="-1">5. Эффективность (DCF, ставка 20%, горизонт 3 года) <a class="header-anchor" href="#_5-эффективность-dcf-ставка-20-горизонт-3-года" aria-label="Permalink to &quot;5. Эффективность (DCF, ставка 20%, горизонт 3 года)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Показатель</th><th style="text-align:left;">Значение</th></tr></thead><tbody><tr><td style="text-align:left;">NPV</td><td style="text-align:left;"><strong>23,3 млн ₽</strong></td></tr><tr><td style="text-align:left;">PI</td><td style="text-align:left;">2,03</td></tr><tr><td style="text-align:left;">IRR</td><td style="text-align:left;">48,5%</td></tr><tr><td style="text-align:left;">DPP</td><td style="text-align:left;">конец 3-го года (кумулятивный DCF: −19,9 → −42,5 → −29,6 → <strong>+3,4</strong> млн ₽)</td></tr><tr><td style="text-align:left;">Break-even</td><td style="text-align:left;"><strong>19 подписок</strong> ≈ 0,07% SAM; операционная рентабельность при 60–80 подписчиках</td></tr><tr><td style="text-align:left;">Операционный рычаг (DOL)</td><td style="text-align:left;">≈ 3,2 (1% роста выручки → 3,2% роста прибыли)</td></tr></tbody></table><h2 id="_6-чувствительность-и-стресс-границы-npv-0" tabindex="-1">6. Чувствительность и стресс-границы (NPV = 0) <a class="header-anchor" href="#_6-чувствительность-и-стресс-границы-npv-0" aria-label="Permalink to &quot;6. Чувствительность и стресс-границы (NPV = 0)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Фактор</th><th style="text-align:left;">Изменение</th><th style="text-align:left;">ΔNPV</th><th style="text-align:left;">Эластичность</th><th style="text-align:left;">Риск</th></tr></thead><tbody><tr><td style="text-align:left;">Выручка (подписки)</td><td style="text-align:left;">−20%</td><td style="text-align:left;">−38%</td><td style="text-align:left;">1,9</td><td style="text-align:left;">🔴 критическая</td></tr><tr><td style="text-align:left;">CAPEX</td><td style="text-align:left;">+20%</td><td style="text-align:left;">−18%</td><td style="text-align:left;">0,9</td><td style="text-align:left;">средняя</td></tr><tr><td style="text-align:left;">OPEX</td><td style="text-align:left;">+20%</td><td style="text-align:left;">−12%</td><td style="text-align:left;">0,6</td><td style="text-align:left;">низкая</td></tr></tbody></table><p>Пределы прочности: цена подписки −35% (Business ниже 48к ₽ — не окупается за 3 года) · CAPEX +45% · churn 15%/мес → операционный убыток. <strong>Главный риск — коммерческий (объём продаж), не технический.</strong></p><p>Сценарии: оптимистичный 45,2 млн ₽ (P=20%) · базовый 23,3 (P=60%) · пессимистичный 4,8 (P=20%).</p><h2 id="_7-команда-и-ресурсы" tabindex="-1">7. Команда и ресурсы <a class="header-anchor" href="#_7-команда-и-ресурсы" aria-label="Permalink to &quot;7. Команда и ресурсы&quot;">​</a></h2><p>Модель «Core Team + Outstaff», 3 стрима:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Стрим</th><th style="text-align:left;">Состав</th></tr></thead><tbody><tr><td style="text-align:left;">AI/ML</td><td style="text-align:left;">Lead Data Scientist ×1, NLP/OCR Engineer ×2</td></tr><tr><td style="text-align:left;">Платформа и данные</td><td style="text-align:left;">Senior Backend ×1, Data Engineer/Architect ×1, Frontend ×1</td></tr><tr><td style="text-align:left;">Продукт и бизнес</td><td style="text-align:left;">Product Manager ×1, DevOps ×0.5 (outsource)</td></tr></tbody></table><p>Фазы найма: M1–M3 R&amp;D (бюджет найма 1,2 млн ₽, прототип ядра) → M4–M6 Product (0,8 млн ₽, интерфейс + CRM + пилоты) → M7+ Scale (0,5 млн ₽, продажи и поддержка).</p><p><strong>Инфраструктура:</strong> аренда GPU (дообучение моделей) + CPU-кластеры (inference), PostgreSQL+pgvector, Redis, <strong>S3-совместимое хранилище для оригиналов PDF/XLS</strong> (→ [[Architecture_Agelto]] §13). Диверсификация облаков (Yandex Cloud / Cloud.ru / Selectel) + Reserved Instances — митигация [[Risk_Register (Agelto)]] R-6/R-7.</p><p><strong>База знаний</strong> (критический актив): нормативные коллекции КТРУ/КСР (регулярное обновление — BRD F-MDM), обучающая выборка 50 000+ размеченных строк, пользовательские прайс-листы.</p><h2 id="_8-региональныи-gtm-аргумент-для-гос-сегмента" tabindex="-1">8. Региональный / GTM-аргумент для гос-сегмента <a class="header-anchor" href="#_8-региональныи-gtm-аргумент-для-гос-сегмента" aria-label="Permalink to &quot;8. Региональный / GTM-аргумент для гос-сегмента&quot;">​</a></h2><ul><li>+25–30% участников на лот (ликвидация «скрытых» позиций в сметах) → рыночное ценообразование</li><li>Экономия до 5–7% НМЦК для бюджета за счёт роста конкуренции</li><li>Уведомления локальным заводам о закупках «их» продукции → рост местного производства и налоговой базы</li></ul><p>Аргументы для продаж через программы цифровизации регионов и анти-коррупционную повестку.</p>',29)])])}const f=e(r,[["render",n]]);export{y as __pageData,f as default};
